/**
 * Host operators may target one owner or all owners. Without an explicit scope, uses the configured stub owner. Returns partial counts and per-photo failures; an error means the run did not fully succeed.
 * @summary Refresh photo coordinates or place names
 */
export const backfillGps = (
    gPSBackfillRequest: NonReadonly<GPSBackfillRequest>,
 options?: SecondParameter<typeof request<GPSBackfillResult>>,) => {
      return request<GPSBackfillResult>(
      {url: `/api/v1/operator/gps/backfill`, method: 'POST',
      headers: {'Content-Type': 'application/json', },
      data: gPSBackfillRequest
    },
      options);
    }

/**
 * Host-operator recovery: removes the credential and revokes unlock sessions without revealing hidden media. Requires explicit confirmation and an owner in header mode.
 * @summary Reset a hidden-media passcode
 */
export const resetHiddenPasscode = (
    resetHiddenRequest: NonReadonly<ResetHiddenRequest>,
 options?: SecondParameter<typeof request<ResetHiddenResult>>,) => {
      return request<ResetHiddenResult>(
      {url: `/api/v1/operator/hidden/reset`, method: 'POST',
      headers: {'Content-Type': 'application/json', },
      data: resetHiddenRequest
    },
      options);
    }

/**
 * Returns newline-delimited JSON progress followed by one result, including partial counts and errors. HTTP 200 only means the stream started. Disconnect cancels unfinished work; completed files remain imported.
 * @summary Import host files and stream progress
 */
export const importMedia = (
    importRequest: NonReadonly<ImportRequest>,
 options?: SecondParameter<typeof request<ImportEvent>>,) => {
      return request<ImportEvent>(
      {url: `/api/v1/operator/imports`, method: 'POST',
      headers: {'Content-Type': 'application/json', },
      data: importRequest
    },
      options);
    }

